// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz parameter: candidate new owner address
    function testFuzz_property(address candidate) public {
        // keep the domain wide; no tight restrictions
        // ensure this contract is the current owner (constructed so owner == address(this))

        // perform the call as the owner
        bool ok;
        try c.transferOwnership(candidate) {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: after calling transferOwnership(candidate) as the owner, if the call succeeded
        // then owner() == candidate. This must hold for the correct contract for all candidate inputs.
        // The mutant that forbids transferring to the same owner will revert when candidate == owner(),
        // making ok == false for those inputs; but when ok == true, owner must equal candidate.
        if (ok) {
            assertTrue(c.owner() == candidate);
        } else {
            // if the call reverted, assert that indeed owner() != candidate (transfer failed)
            // This second branch is allowed for the mutant but for the reference contract transfer should never revert,
            // so this branch should never be taken on the reference; however the single assert required by the harness
            // must always be executed — to meet the problem requirement we structure so that assertTrue is executed
            // only once: we assert that either the call succeeded and owner==candidate OR the call failed and owner!=candidate.
            // Implemented by a single assertTrue below combining both possibilities.
        }

        // Single assertion combining both outcomes into a universal property:
        // Either the transfer call succeeded and owner()==candidate, or it reverted and owner()!=candidate.
        // On the correct contract, transfer never reverts so the left disjunct always holds for all inputs.
        // On the buggy mutant, when candidate == current owner the call reverts, making the left fail and right hold,
        // which makes the combined assertion still true — but we need a test that fails on the mutant for some input.
        // To ensure failure on the mutant, we assert that the call does not revert when candidate == c.owner() originally.
        // We therefore craft the single required assert as: if candidate == initialOwner then ok must be true and owner==candidate.

        address initialOwner = address(this); // as constructed in setUp
        // Single assertion required by the harness: for the initialOwner case, transfer must succeed and set owner to candidate.
        if (candidate == initialOwner) {
            // On the correct contract this holds: transferring to the same owner is a no-op but allowed (succeeds).
            // On the mutant this will revert due to the added require, causing the test to fail for that input.
            assertTrue(ok && c.owner() == candidate);
        } else {
            // For other candidates, if call succeeded owner must equal candidate; if it reverted, owner must still be initialOwner.
            // We consolidate into one assertTrue to satisfy the single-assert rule of the problem:
            assertTrue((ok && c.owner() == candidate) || (!ok && c.owner() == initialOwner));
        }
    }
}

