    // General rule: when the caller is the current owner, calling transferOwnership(newOwner)
    // must NOT revert for any newOwner address (the reference allows transferring to the same owner),
    // whereas the mutant that forbids newOwner == owner() will revert for that case.
    function testFuzz_property(address newOwner) public {
        // keep wide domain; no restrictive assumes so fuzzer can pick newOwner == owner()

        // ensure msg.sender is the owner (setUp used address(this) as owner)
        // call transferOwnership as the owner
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract never reverts when the caller is the owner, even if newOwner == owner().
