pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed parameter: whether to renounce before attempting transferOwnership
    function testFuzz_property(bool renounceFirst) public {
        // general admissible domain: renounceFirst can be true or false

        // initial owner is address(this) (set in constructor via _msgSender())
        address initialOwner = c.owner();
        // sanity: initial owner must be non-zero
        assertTrue(initialOwner != address(0));

        // If renounceFirst, renounce ownership so owner() becomes address(0)
        if (renounceFirst) {
            // call renounceOwnership as the owner
            c.renounceOwnership();
        }

        // Now attempt to transfer ownership from the current caller (we are the owner only if not renounced)
        bool ok;
        try c.transferOwnership(address(1)) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE as an assertion over c's public behaviour:
        // In the reference contract, transferOwnership called by the (current) owner should succeed (ok == true)
        // for both cases where owner was non-zero (normal) and when owner is zero it should revert earlier when caller is not owner.
        // But here we invoked transferOwnership while msg.sender is the original owner; if we renounced first, we are no longer the owner
        // and transferOwnership should therefore revert (ok == false). If we did not renounce, transferOwnership should succeed (ok == true).
        // Combined property: ok equals (renounceFirst ? false : true)
        assertTrue(ok == (!renounceFirst));
    }
}

