pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzz parameters: newOwner (address to transfer to) and doRenounce (whether the current owner will first renounce)
    function testFuzz_property(address newOwner, bool doRenounce) public {
        // Keep domain wide: newOwner can be any address
        // Setup: initial owner is address(this) (the deployer used in setUp)

        // If doRenounce is true, the owner will renounce first (making owner() == address(0))
        if (doRenounce) {
            // renounceOwnership is onlyOwner; call as owner
            c.renounceOwnership();
        }

        // Now attempt to call transferOwnership(newOwner) as the current caller (address(this))
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): If the caller is the current owner before the call and owner() was non-zero,
        // then transferOwnership must succeed and update owner() to newOwner.
        // We observe owner() before deciding: we must read it prior to the transfer attempt — but we already changed state when renouncing.
        // So compute the precondition: callerIsOwnerBefore = (address(this) == ownerBefore) and ownerBefore != address(0)

        // We read owner() from the contract now to determine current owner after any renounce; but we need owner before call.
        // To obey the one-assert rule and only observe c via public API, we derive ownerBefore from doRenounce (since setUp owner is address(this)).
        address ownerBefore = doRenounce ? address(0) : address(this);

        // If caller was ownerBefore and ownerBefore != zero, then reference contract guarantees transferOwnership succeeds.
        // So the property: if (ownerBefore == address(this) && ownerBefore != address(0)) then ok must be true and owner() == newOwner.
        if (ownerBefore == address(this) && ownerBefore != address(0)) {
            // Single assertion required: combine success and final owner check into one boolean
            assertTrue(ok && c.owner() == newOwner);
        } else {
            // If precondition not met (caller wasn't owner or owner was zero), the reference contract may revert or behave differently;
            // we still must make exactly one assertion. In this branch the general rule places no requirement, so assertTrue(true).
            assertTrue(true);
        }
    }
}
